#include "lexer.h"
#include <stdio.h>
#include "array.h"
#include "ctx.h"
#include "lexer_internal.h"

/**
 * @brief provides next token from the stdin stream
 *
 * @param ctx context of the compiler
 * @return next token from the stdin stream
 */
// AI generated by: Zed / GPT-6.1 Sol
// Prompt: "Can you split [@lexer.c](file:///home/daalbu/Code/IFJ26/src/lexer.c)
// into more files like lexer_helpers.c" Changes: Keep token scanning here and
// delegate to the extracted private modules.
Token next_token(Ctx* ctx) {
  // buffer for pushback
  LexerByteBuffer* buffer = &ctx->lexer.buffer;

  // initialized token
  Token token = {.type = EOF_TOKEN,
                 .value = {.integer = 0},
                 .value_type = INTEGER,
                 .line = ctx->lexer.line,
                 .column = ctx->lexer.column};

  State current_state = START;
  State saved_state = START;
  size_t saved_cursor = 0;
  size_t saved_line = 0;
  size_t saved_column = 0;
  bool have_checkpoint = false;

  LexerStack* stack = &ctx->lexer.stack;
  LexerStack* saved_stack = &ctx->lexer.saved_stack;
  // Initialize stack if empty
  if (stack->count == 0) {
    array_append(ctx, stack, STACK_EMPTY);
  }

  size_t token_start = ctx->lexer.cursor;

  // main greedy loop
  while (true) {
    int current;

    // fetching next char from buffer if possible, otherwise save new to buffer
    if (buffer->count > ctx->lexer.cursor) {
      current = buffer->data[ctx->lexer.cursor];
      ctx->lexer.cursor++;
    } else {
      current = getchar();
      if (current >= 0) {
        array_append(ctx, buffer, current);
        ctx->lexer.cursor++;
      } else {
        // EOF - no more characters
      }
    }

    // indentation handling
    // AI generated by: Codex / gpt-6.1-sol
    // Prompt: "Fixed missing semantic analyze, fix the error"
    // Changes: Let string newlines reach the existing string transitions.
    if (current == '\n' &&
        stack->data[stack->count - 1] != STACK_MULTILINE_S_STRING &&
        stack->data[stack->count - 1] != STACK_S_STRING &&
        (current_state == START || current_state == WHITESPACE_STATE)) {
      ctx->lexer.indent_flag = INDENTATION;
      ctx->lexer.indent_level = 0;
      // AI generated by: Codex / gpt-6.1-sol
      // Prompt: "Fixed missing semantic analyze, fix the error"
      // Changes: Advance source position on the fast-path newline.
      ctx->lexer.line++;
      ctx->lexer.column = 1;
      token.type = EOL_TOKEN;
      lexer_discard_consumed(ctx);
      return token;
    }

    if (current_state == START) {
      if ((ctx->lexer.indent_flag == INDENTATION ||
           ctx->lexer.indent_flag == INVALID_INDENTATION) &&
          current == EOF) {
        ctx->lexer.indent_flag = NOT_ACTIVE;
        ctx->lexer.indent_level = 0;
        token_start = ctx->lexer.cursor;

        // previous token was a newline and current is a space
      } else if (ctx->lexer.indent_flag == INDENTATION && current == ' ') {
        ctx->lexer.indent_level++;
        lexer_discard_consumed(ctx);
        token_start = 0;
        continue;

        // indentation error - tab or vertical tab
      } else if (ctx->lexer.indent_flag != NOT_ACTIVE &&
                 (current == '\t' || current == '\v' || current == '\f' ||
                  current == '\r')) {
        ctx->lexer.indent_flag = INVALID_INDENTATION;
        continue;

        // return indent token
      } else if (ctx->lexer.indent_flag == INDENTATION && current != EOF) {
        ctx->lexer.indent_flag = NOT_ACTIVE;
        ctx->lexer.cursor -= 1;

        if (ctx->lexer.indent_level != 0) {
          token.type = INDENT;
          token.value_type = INTEGER;
          token.value.integer = ctx->lexer.indent_level;
          lexer_discard_consumed(ctx);

          return token;
        } else {
          continue;
        }
      }
    }

    if (ctx->lexer.indent_flag == INVALID_INDENTATION && current != ' ' &&
        current != EOF && current != '\t' && current != '\v' &&
        current != '\f' && current != '\r') {
      THROW(E_LEXER_ERROR, "indentation error");
    }

    // AI generated by: Codex / gpt-6.1-sol
    // Prompt: "Fixed missing semantic analyze, fix the error"
    // Changes: Track source positions before recording accepting checkpoints.
    if (current == '\n') {
      ctx->lexer.line++;
      ctx->lexer.column = 1;
    } else if (current != EOF) {
      ctx->lexer.column++;
    }

    // top of the stack
    int top = stack->count == 0 ? STACK_EMPTY : stack->data[stack->count - 1];

    const Transition* transition =
        lexer_find_transition(current_state, current, top);
    if (transition == NULL) {
      if (current == EOF) {
        // return EOF if it is the last token
        if (current_state == START && ctx->lexer.cursor == token_start &&
            stack->count == 1 && top == STACK_EMPTY) {
          token.type = EOF_TOKEN;
          lexer_discard_consumed(ctx);
          return token;
        }
        if (stack->count != 1 && top != STACK_EMPTY) {
          THROW(E_LEXER_ERROR, "unfinished token");  // TODO: better error
        }
        if (current_state == SLASH_ASTERISK ||
            current_state == INSIDE_BLOCK_COMMENT ||
            current_state == INSIDE_MULTILINE_BLOCK_COMMENT ||
            current_state == SLASH_DOUBLE_ASTERISK_1 ||
            current_state == SLASH_DOUBLE_ASTERISK_2 ||
            current_state == POTENTIAL_NESTING || current_state == NESTING) {
          THROW(E_LEXER_ERROR, "unfinished token");  // TODO: better error
        }
        // line comment ends with eof
        if (current_state == COMMENT) {
          if (lexer_populate_token(ctx, &token, EOL_OR_EOF,
                                   (const char*)buffer->data + token_start,
                                   saved_cursor - token_start)) {
            lexer_discard_consumed(ctx);
            return token;
          }
        }
        // return the token if it is accepting before EOF
        if (lexer_state_accepting(current_state)) {
          if (lexer_populate_token(ctx, &token, current_state,
                                   (const char*)buffer->data + token_start,
                                   saved_cursor - token_start)) {
            lexer_discard_consumed(ctx);
            return token;
          }
        }
      }
      if (have_checkpoint) {
        ctx->lexer.cursor = saved_cursor;
        ctx->lexer.line = saved_line;
        ctx->lexer.column = saved_column;
        current_state = saved_state;
        lexer_copy_stack(ctx, stack, saved_stack);

        if (lexer_populate_token(ctx, &token, current_state,
                                 (const char*)buffer->data + token_start,
                                 saved_cursor - token_start)) {
          lexer_discard_consumed(ctx);
          return token;
        }
        lexer_discard_consumed(ctx);
        current_state = START;
        saved_state = START;
        have_checkpoint = false;
        token_start = ctx->lexer.cursor;
        token.line = ctx->lexer.line;
        token.column = ctx->lexer.column;
        continue;
      }

      THROW(E_LEXER_ERROR,
            "Invalid or incomplete token");  // TODO: add line and column
    } else {
      switch (transition->stack_action) {
        case TRANSITION_KEEP:
          break;
        case TRANSITION_PUSH:
          array_append(ctx, stack, transition->stack_symbol);
          break;
        case TRANSITION_POP:
          array_remove(ctx, stack, stack->count - 1);  // remove last
          break;
        case TRANSITION_REPLACE:
          array_remove(ctx, stack, stack->count - 1);  // remove last
          array_append(ctx, stack, transition->stack_symbol);
          break;
      }

      current_state = transition->next_state;

      // newlines after comment handling for indentation
      if (current_state == EOL_OR_EOF && current == '\n') {
        ctx->lexer.indent_flag = INDENTATION;
        ctx->lexer.indent_level = 0;
      }

      // update last_accepting state, save cursor and stack
      // when going to accepting state
      if (lexer_state_accepting(current_state)) {
        saved_state = current_state;
        // save cursor
        saved_cursor = ctx->lexer.cursor;
        // save line and column
        saved_line = ctx->lexer.line;
        saved_column = ctx->lexer.column;
        // save stack
        lexer_copy_stack(ctx, saved_stack, stack);
        have_checkpoint = true;
      }
    }
  }
}
